  // SEC_CM: CTR.REDUN
  prim_count #(
    .Width(AddrWidth),
    .OutSelDnCnt(0), // count up
    .CntStyle(prim_count_pkg::DupCnt)
  ) u_prim_count (
    .clk_i,
    .rst_ni,
    .clr_i(init_trig),
    .set_i(1'b0),
    .set_cnt_i('0),
    .en_i(init_req),
    .step_i(AddrWidth'(1)),
    .cnt_o(init_cnt),
