  prim_onehot_check #(
    .AddrWidth(5),
    .AddrCheck(1),
    .EnableCheck(1)
  ) u_prim_onehot_check (
    .clk_i,
    .rst_ni,
    .oh_i(we_onehot_buf),
    .addr_i(wr_addr_i),
    .en_i(wr_en_i),
    .err_o(we_err)
